"use client"

import { useEffect, useRef, useState } from "react"
import Image from "next/image"
import Link from "next/link"
import { DownloadIcon, ImagePlusIcon } from "lucide-react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardTitle,
} from "@/components/ui/card"
import { formatCompact } from "@/lib/livepeer"

type ContainerPostCardProps = {
  creator: string
  description: string
  image: string
  preload?: boolean
  pullCount?: number
  slug: string
}

function ContainerPostCard({
  creator,
  description,
  image,
  preload = false,
  pullCount,
  slug,
}: ContainerPostCardProps) {
  const inputRef = useRef<HTMLInputElement>(null)
  const [imageSrc, setImageSrc] = useState(image)

  useEffect(() => {
    return () => {
      if (imageSrc.startsWith("blob:")) URL.revokeObjectURL(imageSrc)
    }
  }, [imageSrc])

  function assignImage(file?: File) {
    if (!file) return

    setImageSrc((current) => {
      if (current.startsWith("blob:")) URL.revokeObjectURL(current)
      return URL.createObjectURL(file)
    })
  }

  return (
    <Card className="h-full gap-0 bg-background py-0">
      <div className="flex items-center justify-between gap-3 py-4">
        <div className="flex min-w-0 items-center gap-3">
          <Avatar size="sm">
            <AvatarFallback className="bg-foreground text-background">
              {creator.charAt(0)}
            </AvatarFallback>
          </Avatar>
          <p className="truncate text-sm font-medium">{creator}</p>
        </div>
        {pullCount !== undefined && (
          <span className="flex shrink-0 items-center gap-1.5 text-xs font-medium tabular-nums">
            <DownloadIcon
              className="size-3.5 text-muted-foreground"
              aria-hidden="true"
            />
            {formatCompact(pullCount)}
            <span className="sr-only">pulls</span>
          </span>
        )}
      </div>

      <div className="group/media relative aspect-[4/3] overflow-hidden bg-muted">
        <Image
          src={imageSrc}
          alt={`${slug} container thumbnail`}
          fill
          preload={preload && !imageSrc.startsWith("blob:")}
          unoptimized={imageSrc.startsWith("blob:")}
          className="object-cover transition-transform duration-300 group-hover/media:scale-[1.015]"
          sizes="(min-width: 1024px) 33vw, (min-width: 640px) 50vw, 100vw"
        />
        <Link
          href={`/mockups/livepeer-agent/inference/${slug}`}
          className="absolute inset-0 outline-none focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:ring-inset"
        >
          <span className="sr-only">Open {slug}</span>
        </Link>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          className="absolute top-3 right-3 z-10 opacity-0 shadow-sm transition-opacity group-hover/media:opacity-100 focus-visible:opacity-100 max-sm:opacity-100"
          onClick={() => inputRef.current?.click()}
        >
          <ImagePlusIcon />
          Change image
        </Button>
        <input
          ref={inputRef}
          type="file"
          accept="image/*"
          className="sr-only"
          tabIndex={-1}
          onChange={(event) => assignImage(event.target.files?.[0])}
        />
      </div>

      <CardContent className="px-0 pt-3 pb-5">
        <div className="flex flex-col gap-1.5">
          <Link
            href={`/mockups/livepeer-agent/inference/${slug}`}
            className="w-fit rounded-sm outline-none focus-visible:ring-3 focus-visible:ring-ring/30"
          >
            <CardTitle className="text-base">{slug}</CardTitle>
          </Link>
          <CardDescription className="line-clamp-2">
            {description}
          </CardDescription>
        </div>
      </CardContent>
    </Card>
  )
}

export { ContainerPostCard }

const REGISTRY_URL = "https://livepeer-network-api.cloudspe.com/api/v1"
const LEADERBOARD_URL =
  "https://leaderboard-serverless.vercel.app/api/aggregated_stats"

export type NetworkStats = {
  payoutsUsd24h: number
  rewardsUsd24h: number
}

export type Orchestrator = {
  address: string
  name: string
  serviceHost: string
  stakeLpt: number
  feeCutPercent: number
  active: boolean
  successRate: number | null
}

export type OrchestratorPage = {
  orchestrators: Orchestrator[]
  nextCursor: string | null
}

type RawOrchestrator = {
  address: string
  display_name?: string
  service_uri?: string
  total_stake?: string
  fee_cut_percent?: string
  is_active?: boolean
}

type RegionStats = Record<
  string,
  { success_rate: number; round_trip_score: number; score: number }
>

export async function getNetworkStats(): Promise<NetworkStats | null> {
  try {
    const res = await fetch(`${REGISTRY_URL}/network/stats`, {
      next: { revalidate: 600 },
    })
    if (!res.ok) return null
    const raw = await res.json()
    return {
      payoutsUsd24h: Number(raw.payouts_usd_24h ?? 0),
      rewardsUsd24h: Number(raw.rewards_usd_24h ?? 0),
    }
  } catch {
    return null
  }
}

export async function getOrchestratorsPage({
  cursor,
  limit = 50,
}: {
  cursor?: string
  limit?: number
} = {}): Promise<OrchestratorPage | null> {
  try {
    const params = new URLSearchParams({ limit: String(limit) })
    if (cursor) params.set("cursor", cursor)

    const [orchRes, statsRes] = await Promise.all([
      fetch(`${REGISTRY_URL}/orchestrators?${params}`, {
        next: { revalidate: 600 },
      }),
      fetch(LEADERBOARD_URL, { next: { revalidate: 600 } }),
    ])
    if (!orchRes.ok) return null
    const raw: {
      data: RawOrchestrator[]
      meta?: { next_cursor?: string | null }
    } = await orchRes.json()
    const stats: Record<string, RegionStats> = statsRes.ok
      ? await statsRes.json()
      : {}

    return {
      orchestrators: (raw.data ?? []).map((orch) => {
        const regions = Object.values(stats[orch.address.toLowerCase()] ?? {})
        const successRate =
          regions.length > 0
            ? regions.reduce((sum, region) => sum + region.success_rate, 0) /
              regions.length
            : null
        return {
          address: orch.address,
          name: orch.display_name || shortAddress(orch.address),
          serviceHost: hostFromUri(orch.service_uri),
          stakeLpt: Number(orch.total_stake ?? 0),
          feeCutPercent: Number(orch.fee_cut_percent ?? 0),
          active: Boolean(orch.is_active),
          successRate,
        }
      }),
      nextCursor: raw.meta?.next_cursor ?? null,
    }
  } catch {
    return null
  }
}

const DOCKER_HUB_URL = "https://hub.docker.com/v2/repositories/livepeer"

export type ContainerImage = {
  tag: string
  sizeGb: number
  updatedAt: string
}

export type ContainerHubInfo = {
  pullCount: number
  updatedAt: string
  images: ContainerImage[]
}

export async function getContainerHubInfo(
  slug: string,
  tags: string[]
): Promise<ContainerHubInfo | null> {
  try {
    const [repoRes, ...tagResults] = await Promise.all([
      fetch(`${DOCKER_HUB_URL}/${slug}/`, { next: { revalidate: 3600 } }),
      ...tags.map((tag) =>
        fetch(`${DOCKER_HUB_URL}/${slug}/tags/${tag}`, {
          next: { revalidate: 3600 },
        })
      ),
    ])
    if (!repoRes.ok) return null
    const repo = await repoRes.json()
    const images: ContainerImage[] = []
    for (const res of tagResults) {
      if (!res.ok) continue
      const tag = await res.json()
      images.push({
        tag: tag.name,
        sizeGb: tag.full_size / 1e9,
        updatedAt: tag.last_updated,
      })
    }
    return {
      pullCount: Number(repo.pull_count ?? 0),
      updatedAt: String(repo.last_updated ?? ""),
      images,
    }
  } catch {
    return null
  }
}

export type GithubRepoInfo = {
  stars: number
  license: string | null
  contributors: string[]
}

export async function getGithubRepoInfo(
  repo: string
): Promise<GithubRepoInfo | null> {
  try {
    const [repoRes, contributorsRes] = await Promise.all([
      fetch(`https://api.github.com/repos/${repo}`, {
        next: { revalidate: 3600 },
      }),
      fetch(`https://api.github.com/repos/${repo}/contributors?per_page=5`, {
        next: { revalidate: 3600 },
      }),
    ])
    if (!repoRes.ok) return null
    const raw = await repoRes.json()
    const contributors: { login: string }[] = contributorsRes.ok
      ? await contributorsRes.json()
      : []
    return {
      stars: Number(raw.stargazers_count ?? 0),
      license: raw.license?.spdx_id ?? null,
      contributors: contributors.map((c) => c.login),
    }
  } catch {
    return null
  }
}

function hostFromUri(uri: string | undefined) {
  if (!uri) return ""
  try {
    return new URL(uri).hostname
  } catch {
    return uri
  }
}

export function formatCompact(value: number) {
  return Intl.NumberFormat("en-US", {
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(value)
}

export function shortAddress(address: string) {
  return `${address.slice(0, 6)}…${address.slice(-4)}`
}
